p=R/'receipts'/'r03_c05_s04_04_a01.json';d=json.loads(p.read_text());d['originalPreparedPromptFile']=d['promptFile'];d['promptFile']=str(R/'prompts'/'r03_c05_s04_04_a01_actual-retry.txt');d['attemptHistoryNote']='Prior running call was interrupted/lost and no returned output was found. Saved a01 was generated by the recorded shorter retry prompt; original prepared prompt preserved.';write(p,d)
